# One-Factor Group CFA. Options, results and panel: jamovi/groupCfaOne.*.yaml
# (generated by tools/gen_yaml.py); jmvtools generates R/groupCfaOne.h.R.
# All of the work is shared with groupCfaCorr: see R/jmv-invariance.R.

groupCfaOneClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "groupCfaOneClass",
  inherit = groupCfaOneBase,
  private = list(
    .factors = function() {
      vars <- self$options$vars
      if (!length(vars)) return(list())
      name <- trimws(self$options$factorName)
      stats::setNames(list(vars), if (nzchar(name)) name else "Factor")
    },
    .init = function() psw_jmv_inv_init(self, private$.factors()),
    .run = function() psw_jmv_inv_run(self, private$.factors()),
    .diagram = function(image, ...) psw_jmv_diagram(image)
  )
)
